#include <bits/stdc++.h>
using namespace std;

#define N 200010
#define INF 1010000000
#define rep(i, n) for(int i = 0; i < n; ++i)

int main(void) {
	int n, m;
	int a[N];
	int b[N];
	int ans = INF;
	cin >> n >> m;
	rep(i, n)cin >> a[i];
	rep(i, m)cin >> b[i];
	sort(a, a + n);
	sort(b, b + m);
	int x = 0;
	int y = 0;
	while ((x < n) && (y < m)) {
		ans = min(ans, abs(a[x] - b[y]));
		if (a[x] > b[y])y++;
		else x++;
	}
	cout << ans << endl;

	return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main(){
  int n,m;
  cin>>n>>m;

  vector<pair<int,int>> v;
  for(int i=0;i<n;i++){
    int a;
    cin>>a;
    v.emplace_back(a,1);
  }
  for(int i=0;i<m;i++){
    int b;
    cin>>b;
    v.emplace_back(b,2);
  }

  sort(v.begin(),v.end());

  int ans=2e9;
  for(int i=0;i<n+m-1;i++){
    if(v[i].second!=v[i+1].second){
      ans=min(ans,v[i+1].first-v[i].first);
    }
  }
  cout<<ans<<endl;
}
